import { readFile, writeFile } from "node:fs/promises";

const artifact = JSON.parse(await readFile(new URL("../../../contracts/trueorigin.com/out/TrueOriginPassport.sol/TrueOriginPassport.json", import.meta.url), "utf8"));
if (!Array.isArray(artifact.abi)) throw new Error("Build the passport contract before exporting its ABI.");
const source = [
	"// Generated by generate:contracts from TrueOriginPassport.sol. Do not edit by hand.",
	`export const trueOriginPassportAbi = ${JSON.stringify(artifact.abi, null, "\t")} as const;`,
	`export const trueOriginPassportBytecode = ${JSON.stringify(artifact.bytecode.object)} as const;`,
	`export const trueOriginPassportRuntimeBytecode = ${JSON.stringify(artifact.deployedBytecode.object)} as const;`,
	"",
].join("\n");
const destination = new URL("../src/generated/passport.ts", import.meta.url);
if (process.argv.includes("--check")) {
	if (await readFile(destination, "utf8") !== source) throw new Error("Passport ABI is stale. Run generate:contracts.");
} else {
	await writeFile(destination, source);
}
